import cors from 'cors';
import express from 'express';
import helmet from 'helmet';
import pinoHttp from 'pino-http';
import {
  createSupabaseAdminUserDeleter,
  createSupabaseTokenVerifier,
  type VerifyAccessToken,
} from './auth/supabase-auth';
import { loadEnvironment, type Environment } from './config/env';
import { errorHandler } from './middleware/error-handler';
import { notFoundHandler } from './middleware/not-found';
import {
  createAccountSynchronizer,
  type SynchronizeAccount,
} from './modules/accounts/account.service';
import { createAuthRouter } from './routes/auth.routes';
import { healthRouter } from './routes/health.routes';
import { createPublicReadRouter } from './modules/public-read/public-read.routes';
import {
  createPublicReadService,
  type PublicReadService,
} from './modules/public-read/public-read.service';
import { createFixtureStatisticsRouter } from './modules/statistics/fixture-statistics.routes';
import {
  createFixtureStatisticsService,
  type FixtureStatisticsService,
} from './modules/statistics/fixture-statistics.service';
import { createSubmissionRouter } from './modules/submissions/submission.routes';
import {
  createSubmissionService,
  type SubmissionService,
} from './modules/submissions/submission.service';
import { createSubmitterAccessRouter } from './modules/submitter-access/submitter-access.routes';
import {
  createSubmitterAccessService,
  type SubmitterAccessService,
} from './modules/submitter-access/submitter-access.service';
import { createAccountDeletionRouter } from './modules/account-deletion/account-deletion.routes';
import {
  createAccountDeletionService,
  type AccountDeletionService,
} from './modules/account-deletion/account-deletion.service';
import { createAdminRouter } from './modules/admin/admin.routes';
import { createAdminService, type AdminService } from './modules/admin/admin.service';

export interface AppDependencies {
  environment?: Environment;
  verifyAccessToken?: VerifyAccessToken;
  synchronizeAccount?: SynchronizeAccount;
  publicReadService?: PublicReadService;
  fixtureStatisticsService?: FixtureStatisticsService;
  submissionService?: SubmissionService;
  submitterAccessService?: SubmitterAccessService;
  accountDeletionService?: AccountDeletionService;
  adminService?: AdminService;
}

export function createApp(dependencies: AppDependencies = {}) {
  const environment = dependencies.environment ?? loadEnvironment();
  const verifyAccessToken =
    dependencies.verifyAccessToken ?? createSupabaseTokenVerifier(environment);
  const synchronizeAccount = dependencies.synchronizeAccount ?? createAccountSynchronizer();
  const publicReadService = dependencies.publicReadService ?? createPublicReadService();
  const fixtureStatisticsService =
    dependencies.fixtureStatisticsService ?? createFixtureStatisticsService();
  const submissionService = dependencies.submissionService ?? createSubmissionService();
  const submitterAccessService =
    dependencies.submitterAccessService ?? createSubmitterAccessService();
  const accountDeletionService =
    dependencies.accountDeletionService ??
    createAccountDeletionService(createSupabaseAdminUserDeleter(environment));
  const adminService = dependencies.adminService ?? createAdminService();
  const allowedOrigins = environment.CORS_ORIGINS.split(',')
    .map((origin) => origin.trim())
    .filter(Boolean);

  const app = express();

  app.disable('x-powered-by');
  app.use(helmet());
  app.use(
    cors({
      origin: allowedOrigins,
      credentials: true,
    }),
  );
  app.use(express.json({ limit: '1mb' }));
  app.use(
    pinoHttp({
      redact: ['req.headers.authorization'],
    }),
  );

  app.use('/api/v1/health', healthRouter);
  app.use('/api/v1/auth', createAuthRouter(verifyAccessToken, synchronizeAccount));
  app.use('/api/v1', createFixtureStatisticsRouter(fixtureStatisticsService));
  app.use(
    '/api/v1',
    createSubmissionRouter(verifyAccessToken, synchronizeAccount, submissionService),
  );
  app.use(
    '/api/v1',
    createSubmitterAccessRouter(verifyAccessToken, synchronizeAccount, submitterAccessService),
  );
  app.use(
    '/api/v1',
    createAccountDeletionRouter(verifyAccessToken, synchronizeAccount, accountDeletionService),
  );
  app.use('/api/v1', createAdminRouter(verifyAccessToken, synchronizeAccount, adminService));
  app.use('/api/v1', createPublicReadRouter(publicReadService));

  app.use(notFoundHandler);
  app.use(errorHandler);

  return app;
}

The CLI requires a Docker-compatible runtime.

Local Supabase configuration must be coordinated with the database workstream. Do not initialize or reset a shared database without team agreement.

A local stack is for development only. It has development credentials and must never be exposed publicly.

## Password reset

Supabase Auth provides managed password-reset operations and email flows.

The final password-reset page, redirect handling, email templates and production SMTP configuration remain future work.

The hosted default email service has development rate limits. Production use requires appropriate SMTP configuration and monitoring.

## Account deletion

Authenticated users can delete their own account with `DELETE /api/v1/account`. The endpoint accepts
no target account ID and requires both an exact `DELETE` confirmation and a Supabase
`last_sign_in_at` no more than 15 minutes old. Older sessions receive `403
RECENT_AUTHENTICATION_REQUIRED` and must sign in again.

Deletion runs only on the backend with `SUPABASE_SECRET_KEY`. The key must be a Supabase secret key
or legacy `service_role` key and must never use a `VITE_` prefix or enter browser code. The backend
uses the Auth Admin API for a hard deletion.

The local workflow is a recoverable state machine:

1. disable the application account and remove role, approval and competition grants;
2. hard-delete the Supabase Auth user;
3. replace the local Auth subject and display name with a non-reusable tombstone while retaining the
   stable `app_user_id` provenance key; and
4. clear the browser's local Supabase session after the backend confirms success.

An Auth or database failure returns `503 ACCOUNT_DELETION_INCOMPLETE`. The local account remains
disabled, and retry either repeats the idempotent Auth deletion or resumes finalization. A hash of
the former high-entropy Auth subject prevents an already-issued JWT from synchronizing a replacement
account during the token's remaining lifetime. The browser's local sign-out does not substitute for
the backend revocation check.

Cricket submissions, deliveries, fixtures and derived statistics remain available without the
deleted display name or reusable Auth subject.

See:

- [Privacy and retention](privacy-retention.md)
- `evidence/decisions/ADR-006-account-deletion-retention.md`

## Authentication versus authorisation

Authentication answers:

> Who is making this request?

Authorisation answers:

> What is this identity allowed to do?

A valid Supabase identity does not automatically grant:

- `admin` access;
- `submitter` access;
- competition access;
- season or fixture access;
- event submission rights;
# Environment variables

Real environment files are ignored by Git. Only placeholder examples may be committed.

## Frontend

