$openPulls = Invoke-RestMethod -Method Get -Uri ($apiBase + '/pulls?state=open&limit=50') -Headers $headers
$existingPull = $openPulls | Where-Object { $_.head.ref -eq 'fix/66-publishable-only-supabase' } | Select-Object -First 1
if ($existingPull) {
